/**
 * Fact-audit fix pass, Round 3 (final), group B_mixguides (2026-10-22):
 * Computer B's HEDGE / CONTEXT / CAN'T CONFIRM rows for the mixing guides.
 * Pins a sample of the fixes (new wording present, old wording gone) and
 * checks no guide says comb filtering cancels "pitches" (owner ruling).
 *
 * The guide files are generated by scripts/mixing-guides/; these edits were
 * made in the guide files directly and are listed in the round's ledger
 * (`generated: true`) so the converter can mirror them.
 */
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, it } from 'node:test';

const ROOT = join(import.meta.dirname, '..');
const read = (rel: string) => readFileSync(join(ROOT, rel), 'utf8').replace(/\r\n/g, '\n');
const DATA = 'src/screens/lab/mixingGuides/data';
const g = (name: string) => read(`${DATA}/guides/${name}.ts`);

// [guide file, new wording that must be present, old wording that must be gone]
const PINS: Array<[string, string, string]> = [
  ['g01-pop', 'A packed, singing house can push the level several dB above the soundcheck level.', 'can rise past 110 dB with a packed, singing house'],
  ['g02-hip-hop-rap', 'often plays the bassline and can also act as the kick', 'functions as both kick and bassline'],
  ['g02-hip-hop-rap', 'de-ess before or after the presence boost, then check the S sounds', '2.5–5 kHz; de-ess after the presence boost"'],
  ['g02-hip-hop-rap', 'streaming guides advise −1 dBTP, or −2 dBTP for masters this loud', 'true peak around −1 to 0 dBTP.'],
  ['g02-hip-hop-rap', 'sometimes several compressors in series on one lead vocal', 'dozens of compressors'],
  ['g02-hip-hop-rap', 'Many rappers cup and eat the mic', '"Rappers cup and eat the mic'],
  ['g05-edm-festival-electronic', 'a common cause of muddy big-room drops', 'the main cause of muddy big-room drops'],
  ['g08-reggaeton', 'threshold just under the singer’s quietest line', 'threshold around −55 to −60 dBFS'],
  ['g10-k-pop', 'wave across Asia from the late 1990s, going global in the 2010s', 'global “Hallyu” (Korean pop-culture) wave from the 2010s'],
  ['g13-bollywood-indian-film-music', 'Sitar sympathetic-string shimmer lives above 5 kHz', 'Sitar sympathetic strings live above 5 kHz'],
  ['g14-afrobeats', 'Very fast retune (about 0–20 ms)', 'Fast retune (5–20 ms)'],
  ['g15-classical-orchestral', '(bassoon and bass clarinet about 40–50 Hz)', '(bassoon 50–60 Hz)'],
  ['g15-classical-orchestral', 'Emerson String Quartet, Beethoven The String Quartets, 1997', 'The Late String Quartets, 1996'],
  ['g16-film-video-game-score', 'rarely for primary instruments', 'never primary instruments'],
  ['g16-film-video-game-score', 'keep music mostly out of the center channel', 'some broadcasters forbid music there'],
  ['g20-gospel', 'Subtle; adds width, but not gain before feedback', 'a few dB of headroom before feedback'],
  ['g22-soul', 'some classic Motown stereo mixes put drums on one side', 'I Heard It Through the Grapevine'],
  ['g28-reggae', 'Barrett used big bass cabinets for depth', '18-inch and 4x15 cabinets'],
  ['g31-blues', 'comped from two takes.', 'Stevie Ray Vaughan sang each song twice'],
  ['g34-folk-singer-songwriter', 'If the guitar has a pickup, always get a DI from it', '"Always get a DI from the guitar'],
  ['g38-salsa', 'brings no stage bleed, though its left hand still adds low end', 'brings no mud at all'],
  ['g45-drum-and-bass', 'Loudest to quietest in a drop', 'kick around −18 to −12 dBFS'],
  ['g47-bluegrass-americana', 'C-weighted levels sit only a few dB higher', 'with a small C–A gap'],
  ['g47-bluegrass-americana', 'only a few dB higher in dBC', '~100–105 dBC'],
  ['g48-musical-theatre', 'cross-fade between actors unless both speak at once', 'Never leave two close mics open'],
];

describe('fact audit R3 · mixing guides: hedged and corrected claims', () => {
  for (const [file, now, old] of PINS) {
    it(`${file}: ${now.slice(0, 50)}`, () => {
      const s = g(file);
      assert.ok(s.includes(now), `missing new wording in ${file}: ${now}`);
      assert.ok(!s.includes(old), `old wording still in ${file}: ${old}`);
    });
  }

  it('Afrobeats clave gloss is one or two bars, except where the 3-2 / 2-3 clave is named', () => {
    const s = (g('g14-afrobeats') + read(`${DATA}/index.ts`)).replace('3-2 / 2-3 clave (a 2-bar rhythm key)', '');
    assert.doesNotMatch(s, /clave \(a 2-bar rhythm key\)/);
    assert.match(s, /clave \(a one- or two-bar rhythm key\)/);
  });

  it('index.ts mirrors the K-pop origin fix', () => {
    const s = read(`${DATA}/index.ts`);
    assert.match(s, /wave across Asia from the late 1990s, going global in the 2010s/);
  });

  it('no guide says comb filtering cancels "pitches"', () => {
    for (const f of readdirSync(join(ROOT, DATA, 'guides'))) {
      const s = g(f.replace(/\.ts$/, ''));
      assert.doesNotMatch(s, /pitches (?:cancel|drop out)|cancels? (?:some )?pitches/i, f);
    }
  });
});
